BEGIN;

CREATE TABLE IF NOT EXISTS skolenza."TimetablePeriodMaster" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "InstitutionId" bigint NOT NULL REFERENCES skolenza."Institution"("Id"),
    "AcademicSessionId" bigint NOT NULL REFERENCES skolenza."AcademicSessionMaster"("Id"),
    "CampusId" bigint NULL REFERENCES skolenza."Campus"("Id"),
    "Code" varchar(60) NOT NULL,
    "Name" varchar(150) NOT NULL,
    "Description" varchar(500) NULL,
    "Sequence" smallint NOT NULL,
    "StartTime" time NOT NULL,
    "EndTime" time NOT NULL,
    "IsActive" boolean NOT NULL DEFAULT true,
    "IsSoftDeleted" boolean NOT NULL DEFAULT false,
    "AddedById" bigint NOT NULL,
    "AddedDateTime" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "UpdatedById" bigint NULL,
    "UpdatedDateTime" timestamptz NULL,
    CONSTRAINT "CK_TimetablePeriod_Time" CHECK ("EndTime" > "StartTime"),
    CONSTRAINT "UQ_TimetablePeriod_Institution_Code" UNIQUE ("InstitutionId", "Code")
);

CREATE TABLE IF NOT EXISTS skolenza."TimetableEntry" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "InstitutionId" bigint NOT NULL REFERENCES skolenza."Institution"("Id"),
    "AcademicSessionId" bigint NOT NULL REFERENCES skolenza."AcademicSessionMaster"("Id"),
    "ClassSectionId" bigint NOT NULL REFERENCES skolenza."ClassSectionMaster"("Id"),
    "CourseOfferingId" bigint NOT NULL REFERENCES skolenza."CourseOfferingMaster"("Id"),
    "TimetablePeriodMasterId" bigint NOT NULL REFERENCES skolenza."TimetablePeriodMaster"("Id"),
    "StaffTeachingAssignmentId" bigint NOT NULL REFERENCES skolenza."StaffTeachingAssignment"("Id"),
    "DayOfWeek" smallint NOT NULL,
    "RoomReference" varchar(100) NULL,
    "EffectiveFrom" date NOT NULL,
    "EffectiveTo" date NULL,
    "IsActive" boolean NOT NULL DEFAULT true,
    "IsSoftDeleted" boolean NOT NULL DEFAULT false,
    "AddedById" bigint NOT NULL,
    "AddedDateTime" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "UpdatedById" bigint NULL,
    "UpdatedDateTime" timestamptz NULL,
    CONSTRAINT "CK_TimetableEntry_Day" CHECK ("DayOfWeek" BETWEEN 1 AND 7),
    CONSTRAINT "CK_TimetableEntry_Date" CHECK ("EffectiveTo" IS NULL OR "EffectiveTo" >= "EffectiveFrom")
);
CREATE INDEX IF NOT EXISTS "IX_TimetableEntry_TeacherSlot" ON skolenza."TimetableEntry"
    ("InstitutionId", "StaffTeachingAssignmentId", "DayOfWeek", "TimetablePeriodMasterId", "EffectiveFrom");
CREATE INDEX IF NOT EXISTS "IX_TimetableEntry_SectionSlot" ON skolenza."TimetableEntry"
    ("InstitutionId", "ClassSectionId", "DayOfWeek", "TimetablePeriodMasterId", "EffectiveFrom");

CREATE TABLE IF NOT EXISTS skolenza."SubstituteWorkflowMaster" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "InstitutionId" bigint NOT NULL REFERENCES skolenza."Institution"("Id"),
    "Code" varchar(60) NOT NULL,
    "Name" varchar(150) NOT NULL,
    "Description" varchar(500) NULL,
    "RequiresSubstituteAcceptance" boolean NOT NULL DEFAULT true,
    "AllowSelfNomination" boolean NOT NULL DEFAULT false,
    "AutoApproveWhenNoSteps" boolean NOT NULL DEFAULT false,
    "IsActive" boolean NOT NULL DEFAULT true,
    "IsSoftDeleted" boolean NOT NULL DEFAULT false,
    "AddedById" bigint NOT NULL,
    "AddedDateTime" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "UpdatedById" bigint NULL,
    "UpdatedDateTime" timestamptz NULL,
    CONSTRAINT "UQ_SubstituteWorkflow_Institution_Code" UNIQUE ("InstitutionId", "Code")
);
CREATE TABLE IF NOT EXISTS skolenza."SubstituteWorkflowStep" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "InstitutionId" bigint NOT NULL REFERENCES skolenza."Institution"("Id"),
    "SubstituteWorkflowMasterId" bigint NOT NULL REFERENCES skolenza."SubstituteWorkflowMaster"("Id"),
    "Sequence" smallint NOT NULL,
    "ApproverTypeCode" varchar(40) NOT NULL,
    "AccessRoleId" integer NULL REFERENCES skolenza."Role"("Id"),
    "StaffPositionMasterId" integer NULL REFERENCES skolenza."StaffPositionMaster"("Id"),
    "StaffMemberId" bigint NULL REFERENCES skolenza."StaffMember"("Id"),
    "IsActive" boolean NOT NULL DEFAULT true,
    "AddedById" bigint NOT NULL,
    "AddedDateTime" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "CK_SubstituteStep_Approver" CHECK ("ApproverTypeCode" IN ('MANAGER','ACCESS_ROLE','POSITION','STAFF_MEMBER')),
    CONSTRAINT "UQ_SubstituteStep_Sequence" UNIQUE ("SubstituteWorkflowMasterId", "Sequence")
);
CREATE TABLE IF NOT EXISTS skolenza."StaffAbsenceImpact" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "InstitutionId" bigint NOT NULL REFERENCES skolenza."Institution"("Id"),
    "LeaveRequestId" bigint NOT NULL REFERENCES skolenza."LeaveRequest"("Id"),
    "AbsentStaffMemberId" bigint NOT NULL REFERENCES skolenza."StaffMember"("Id"),
    "TimetableEntryId" bigint NOT NULL REFERENCES skolenza."TimetableEntry"("Id"),
    "ImpactDate" date NOT NULL,
    "StatusCode" varchar(40) NOT NULL,
    "AddedById" bigint NOT NULL,
    "AddedDateTime" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "UpdatedById" bigint NULL,
    "UpdatedDateTime" timestamptz NULL,
    CONSTRAINT "UQ_StaffAbsenceImpact" UNIQUE ("InstitutionId", "LeaveRequestId", "TimetableEntryId", "ImpactDate")
);
CREATE TABLE IF NOT EXISTS skolenza."SubstituteAssignment" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "InstitutionId" bigint NOT NULL REFERENCES skolenza."Institution"("Id"),
    "StaffAbsenceImpactId" bigint NOT NULL UNIQUE REFERENCES skolenza."StaffAbsenceImpact"("Id"),
    "SubstituteWorkflowMasterId" bigint NOT NULL REFERENCES skolenza."SubstituteWorkflowMaster"("Id"),
    "SubstituteStaffMemberId" bigint NOT NULL REFERENCES skolenza."StaffMember"("Id"),
    "StatusCode" varchar(40) NOT NULL,
    "CurrentApprovalSequence" smallint NOT NULL DEFAULT 0,
    "AcceptedDateTime" timestamptz NULL,
    "Remark" varchar(500) NULL,
    "AddedById" bigint NOT NULL,
    "AddedDateTime" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "UpdatedById" bigint NULL,
    "UpdatedDateTime" timestamptz NULL
);
CREATE TABLE IF NOT EXISTS skolenza."SubstituteApprovalHistory" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "InstitutionId" bigint NOT NULL REFERENCES skolenza."Institution"("Id"),
    "SubstituteAssignmentId" bigint NOT NULL REFERENCES skolenza."SubstituteAssignment"("Id"),
    "Sequence" smallint NOT NULL,
    "ActionByStaffMemberId" bigint NOT NULL REFERENCES skolenza."StaffMember"("Id"),
    "ActionCode" varchar(40) NOT NULL,
    "Remark" varchar(500) NULL,
    "ActionDateTime" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS skolenza."InstitutionCommunicationSetting" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "InstitutionId" bigint NOT NULL UNIQUE REFERENCES skolenza."Institution"("Id"),
    "EnableInApp" boolean NOT NULL DEFAULT true,
    "EnableEmail" boolean NOT NULL DEFAULT false,
    "EnableSms" boolean NOT NULL DEFAULT false,
    "EnablePush" boolean NOT NULL DEFAULT false,
    "RetentionDays" integer NOT NULL DEFAULT 365 CHECK ("RetentionDays" BETWEEN 1 AND 3650),
    "IsActive" boolean NOT NULL DEFAULT true,
    "AddedById" bigint NOT NULL,
    "AddedDateTime" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "UpdatedById" bigint NULL,
    "UpdatedDateTime" timestamptz NULL
);
CREATE TABLE IF NOT EXISTS skolenza."StaffQueryCategoryMaster" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "InstitutionId" bigint NOT NULL REFERENCES skolenza."Institution"("Id"),
    "Code" varchar(60) NOT NULL,
    "Name" varchar(150) NOT NULL,
    "Description" varchar(500) NULL,
    "IsActive" boolean NOT NULL DEFAULT true,
    "IsSoftDeleted" boolean NOT NULL DEFAULT false,
    "AddedById" bigint NOT NULL,
    "AddedDateTime" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "UpdatedById" bigint NULL,
    "UpdatedDateTime" timestamptz NULL,
    CONSTRAINT "UQ_StaffQueryCategory_Institution_Code" UNIQUE ("InstitutionId", "Code")
);
CREATE TABLE IF NOT EXISTS skolenza."StaffConversation" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "InstitutionId" bigint NOT NULL REFERENCES skolenza."Institution"("Id"),
    "ConversationTypeCode" varchar(40) NOT NULL CHECK ("ConversationTypeCode" IN ('DIRECT','QUERY','BROADCAST')),
    "StaffQueryCategoryMasterId" bigint NULL REFERENCES skolenza."StaffQueryCategoryMaster"("Id"),
    "Subject" varchar(300) NOT NULL,
    "StatusCode" varchar(40) NOT NULL,
    "CreatedByStaffMemberId" bigint NOT NULL REFERENCES skolenza."StaffMember"("Id"),
    "CreatedDateTime" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "IsClosed" boolean NOT NULL DEFAULT false,
    "ClosedDateTime" timestamptz NULL
);
CREATE TABLE IF NOT EXISTS skolenza."StaffConversationParticipant" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "InstitutionId" bigint NOT NULL REFERENCES skolenza."Institution"("Id"),
    "StaffConversationId" bigint NOT NULL REFERENCES skolenza."StaffConversation"("Id"),
    "StaffMemberId" bigint NOT NULL REFERENCES skolenza."StaffMember"("Id"),
    "ParticipantRoleCode" varchar(40) NOT NULL,
    "LastReadDateTime" timestamptz NULL,
    "IsMuted" boolean NOT NULL DEFAULT false,
    "IsActive" boolean NOT NULL DEFAULT true,
    CONSTRAINT "UQ_StaffConversationParticipant" UNIQUE ("StaffConversationId", "StaffMemberId")
);
CREATE TABLE IF NOT EXISTS skolenza."StaffConversationMessage" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "InstitutionId" bigint NOT NULL REFERENCES skolenza."Institution"("Id"),
    "StaffConversationId" bigint NOT NULL REFERENCES skolenza."StaffConversation"("Id"),
    "SenderStaffMemberId" bigint NOT NULL REFERENCES skolenza."StaffMember"("Id"),
    "Body" varchar(10000) NOT NULL,
    "SentDateTime" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "IsSoftDeleted" boolean NOT NULL DEFAULT false
);
CREATE TABLE IF NOT EXISTS skolenza."StaffMessageAttachment" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "InstitutionId" bigint NOT NULL REFERENCES skolenza."Institution"("Id"),
    "StaffConversationMessageId" bigint NOT NULL REFERENCES skolenza."StaffConversationMessage"("Id"),
    "FileName" varchar(255) NOT NULL,
    "ContentType" varchar(100) NOT NULL,
    "StorageObjectKey" varchar(1000) NOT NULL,
    "FileSize" bigint NOT NULL CHECK ("FileSize" > 0)
);
CREATE TABLE IF NOT EXISTS skolenza."StaffBroadcastAudience" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "InstitutionId" bigint NOT NULL REFERENCES skolenza."Institution"("Id"),
    "StaffConversationId" bigint NOT NULL REFERENCES skolenza."StaffConversation"("Id"),
    "AudienceTypeCode" varchar(40) NOT NULL CHECK ("AudienceTypeCode" IN ('CAMPUS','DEPARTMENT','STAFF_CATEGORY','ACCESS_ROLE','STAFF_MEMBER')),
    "TargetId" bigint NOT NULL,
    CONSTRAINT "UQ_StaffBroadcastAudience" UNIQUE ("StaffConversationId", "AudienceTypeCode", "TargetId")
);

COMMIT;
